(130, 'PT EPSON BATAM', 'Other', NULL, '(0778) 611151', 'peb-recruitment@sep.epson.com.sg', 'epson.com.sg', '-', '-', '-', '-', 'EPSON EXCEED YOUR VISION', 'Jl. Rambutan Lot 504-510 Dan Lot 530, Batamindo Industrial Park, Muka Kuning', 'KEPULAUAN RIAU', 'KOTA BATAM', '&lt;p&gt;-&lt;/p&gt;\\r\\n', 'Verified', '1', 1, NULL, NULL),
(131, 'PT Excelitas Technologies Batam', 'Other', NULL, '+62 770 613450 ', 'limillah.alizzah@excelitas.com', 'https://www.excelitas.com/', '-', '-', '-', 'https://www.linkedin.com/company/excelitas-technologies/', 'https://www.excelitas.com/company-profile', 'Jl. Beringin, Lot 207 Bip, Mukakuning Batam 29433 Indonesia', 'KEPULAUAN RIAU', 'KOTA BATAM', '<p><br />\r\nExcelitas Technologies is a technology leader in delivering high-performance, market-driven photonic innovations to&nbsp;meet the illumination, optical, optronic, sensing, detection and imaging needs&nbsp;of customers worldwide.&nbsp;Serving a vast array of applications across automotive, consumer products, defense and aerospace, industrial, medical, safety and security, and sciences sectors, Excelitas Technologies stands committed to promoting our customers&#39; success.</p>\r\n\r\n<p><strong>Engage</strong></p>\r\n\r\n<p>At Excelitas, we engage with our customers in collaborative engineer-to-engineer relationships. Our photonic solutions teams are involved early in our customers&#39; design cycles, helping them to accelerate time to market and secure unique technological differentiators and ensure barriers to entry for their competitors.</p>\r\n\r\n<p><strong>Enable</strong></p>\r\n\r\n<p>With our extensive integration expertise and diverse photonics technology portfolio, we enable a broad range of&nbsp; innovations and applications including clinical diagnostics, autonomous vehicles, surgical visualization, X-ray security screening, smart home systems, additive manufacturing, IOT products, scientific discovery, semiconductor equipment, medical device assembly, defense and aerospace applications.</p>\r\n\r\n<p><strong>Excel</strong></p>\r\n\r\n<p>Our customized, market-driven solutions for each of our OEM customers&rsquo; unique system requirements &mdash; coupled with a focus on excellence in all aspects of product performance, quality, reliability, delivery and service &mdash; enable our customers to excel in their end-markets and applications.</p>\r\n\r\n<p>Excelitas Technologies Corp. is as an independent company owned by AEA Investors, a leading global private investment firm focused on private equity and debt investments in the middle market.<br />\r\n<br />\r\nCompany Video:<br />\r\n<a href=\"https://www.youtube.com/watch?v=pBmbgb1WixM\">Excelitas Technologies - Enabling the Future Through Light - YouTube</a></p>\r\n', 'Verified', '1', 1, NULL, NULL),
(132, 'PT Federal Investindo', '-', NULL, '-', '-', '-', '-', '-', '-', '-', '-', 'Mega Mall Batam Center\n(Depan International Ferry Terminal Batam Centre) Batam 29432 Indonesia)', 'KEPULAUAN RIAU', 'KOTA BATAM', '-', 'Verified', '1', 1, NULL, NULL),
