(303, 'PT. Cicor Panatec', 'Other', NULL, '(0776) 12233', 'mery.vera@cicor.com', 'www.cicor.com', '', '', '', '-', 'PT. Cicor Panatec', 'Batamindo Industry Park, Jl. Beringin No.323/324, Muka Kuning, Kecamatan Nongsa, Kota Batam, Kepulauan Riau 29432', 'Kepulauan Riau', 'Kota Batam', '&lt;p&gt;PT. Cicor Panatec merupakan salah satu perusahaan perusahaan manufaktur yang memrproduksi barang-barang alat kesehatan, dan injection moulding plastic.&lt;/p&gt;\\r\\n', 'Verified', '1', 1, NULL, NULL),
(304, 'Dinas Kepemudaan dan Olahraga Kota Batam ', 'Government', NULL, '(0778)452711', 'disporakotabatam@gmail.com', 'dispora.batam.go.id', 'disporabatam', '', 'disporabatam', '-', 'https://images.app.goo.gl/aGgoMthnAbf4sne89', 'Gedung Pemuda Hang Jebat Jl. Jendral Sudirman No.8 Kelurahan Sukajadi, Kecamatan Batam Kota', 'Kepulauan Riau', 'Kota Batam', '&lt;p&gt;Pemerintah Kota Batam melalui Dinas Kepemudaan dan Olahraga Kota Batam&amp;nbsp; telah melakukan banyak hal dalam pembenahan dan pembangunan melalui beberapa sektor diantaranya adalah bidang Kepemudaan dan Olahraga baik bersifat pembinaan,prestasi, sarana prasarana.&lt;/p&gt;\\r\\n', 'Verified', '1', 1, NULL, NULL),
