(307, 'SMAN 19 BATAM', 'Pendidikan', NULL, '', '', '', '', '', '', '-', '', 'Jl.Brigjen Katamso Kel.Sei Binti Kec.Sagulung Batam', 'Kepulauan Riau', 'Kota Batam', '', 'Verified', '1', 1, NULL, NULL),
(308, 'PT. Dwi Sumber Arca Waja (DSAW)', 'Manufacturing', NULL, '0778 - 711240', 'haryanto@ptdsaw.co.id', 'http://www.ptdsaw.co.id/', '', '', '', '-', 'http://www.ptdsaw.co.id/image/dsaw_logo_top.png', 'Jl. Hang kesturi I No 8 Kawasan industri terpadu kabil', 'Kepulauan riau', 'Batam', '&lt;p&gt;PT. DWI SUMBER ARCA WAJA was established in 1995 to manufacture large diameter steel pipes and structural tubulars. The Company is a multi-national joint-venture consisting of Indonesia, Singapore, Japan and Europe shareholders. The plant is located at Kabil Industrial Estate, Batam in Indonesia which is about 20 km from Singapore. Including it&amp;#39;s proximity to&amp;nbsp;&lt;a href=&quot;http://www.scnport.com/&quot; target=&quot;_blank&quot;&gt;the port&lt;/a&gt;&amp;nbsp;gives us more benefits.&lt;br /&gt;\r\n&lt;br /&gt;\r\nCustomer requirements, industry standards and established procedures from the basis for our Quality Assurance program, which is certified by ISO 9001 &amp;amp; licensed to manufacture API 2B &amp;amp; 5L.&lt;br /&gt;\r\n&lt;br /&gt;\r\nDSAW&amp;rsquo;s manufacturing system ensures full traceability of all products manufactured with test data are regularly analyzed to ensure quality. Test result are provided to Customers on request.&lt;br /&gt;\r\n&lt;br /&gt;\r\nPT. DSAW has established itself in the international market and is now a major supplier of large Diameter Steel Pipes and Structural Tubulars.&lt;br /&gt;\r\n&lt;br /&gt;\r\nOur products have been applied in Oil and Gas Offshore Platform construction, Pipelines and Pipe Marine, Civil and General Construction.&lt;/p&gt;\r\n', 'Verified', '1', 1, NULL, NULL),
