(582, 'SMK MA\"ARIF NU KOTA BATAM', 'Education', NULL, '-', '-', '-', '-', '-', '-', '-', '-', 'JL.Marina (Depan Perum. Kota Mas) Kel. Tg. Riau Kec. Sekupang', 'Kepulauan Riau', 'Batam', '<p>SMK MA&quot;ARIF NU KOTA BATAM</p>\r\n\r\n<p>JL.Marina (Depan Perum. Kota Mas) Kel. Tg. Riau Kec. Sekupang</p>\r\n', 'Verified', '1', 1, NULL, NULL),
(584, 'PT. Konsultindo Artha Persada', 'Training &amp; Consulting', NULL, 'Santiyopie@kap-sy.com', 'Santiyopie@kap-sy.com', 'https://kap-sy.com/', '-', '-', '-', '-', 'https://kap-sy.com/image/logo.png', 'Komp. Ruko Puri Legenda, Blok C2 No.11, Batam Center', 'Kepulauan Riau', 'Batam', '&lt;p&gt;The company was previously started from accounting services and administrative services and tax consulting&amp;nbsp;&lt;strong&gt;since 2012&lt;/strong&gt;&amp;nbsp;under the name &amp;quot;&lt;strong&gt;SY Consultant&lt;/strong&gt;&amp;quot;. Along with the development of dynamic global trade, the company offers a &amp;quot;&lt;strong&gt;one stop solution service&lt;/strong&gt;&amp;quot; for&lt;strong&gt;&amp;nbsp;international clients to start businesses in Indonesia&lt;/strong&gt;.&amp;nbsp;Additional services that we offer are in the form of training &amp;amp; research, human resources management, and taking care from the legal side until the business can run as well. Therefore, to maximize the resources of this company, we are decided to build a legal entity under the name of&amp;nbsp;&lt;strong&gt;PT. Konsultindo Artha Persada&lt;/strong&gt;&amp;nbsp;which is officially registered on&amp;nbsp;&lt;strong&gt;June 23, 2017&lt;/strong&gt;.&lt;/p&gt;\r\n\r\n&lt;p&gt;The founder of PT. Konsultindo Artha Persada is Ms.&amp;nbsp;&lt;strong&gt;Santi Yopie, SE., MM., CMA., CPA., BKP.&lt;/strong&gt;&amp;nbsp;She is one of Indonesia&amp;rsquo;s leading tax advisory, tax&amp;nbsp;compliance specialized in handling international taxation service providers&amp;nbsp; in Indonesia.&lt;/p&gt;\r\n\r\n&lt;p&gt;Based in Indonesia,&amp;nbsp;PT. Konsultindo Artha Persada is staffed by dedicated professionals with a deep understanding of local Indonesia tax policies and business culture. We are equally well informed on international legislation and trends.&lt;/p&gt;\r\n\r\n&lt;p&gt;Our clients include many of the nation&amp;rsquo;s leading businesses and fastest growing corporations in key sectors such as banking, mining, trading, manufacturing, property, securities and finance, as well as prominent multinationals.&lt;/p&gt;\r\n', 'Verified', '1', 1, NULL, NULL),
(585, 'CV GRIYA LUXURY', 'Other', NULL, '-', '-', '-', '-', '-', '-', '-', '-', 'Ruko Purimas Blok C No.29 Batam Centre, Tlk.Tering, Kec. Batam Kota, Kota Batam, Kepulauan Riau 29444', 'Kepulauan Riau', 'Batam', '<p>CV GRIYA LUXURY</p>\r\n\r\n<p>Ruko Purimas Blok C No.29 Batam Centre, Tlk.Tering, Kec. Batam Kota, Kota Batam, Kepulauan Riau 29444</p>\r\n', 'Verified', '1', 1, NULL, NULL),
