(608, 'Badan Pengawasan Keuangan dan Pembangunan (BPKP) Perwakilan Provinsi Kepulauan Riau', 'Agency', NULL, '+622185910031', '-', 'https://www.bpkp.go.id/kepri.bpkp', '-', '-', '-', '-', 'https://www.bpkp.go.id/public/elusive/img/logo_bpkp.png', 'Jl. RE Martadinata, Tj. Pinggir, Kec. Sekupang, Kota Batam, Kepulauan Riau 29425', 'Kepulauan Riau', 'Kota Batam', '&lt;p&gt;-&lt;/p&gt;\r\n', 'Verified', '1', 1, NULL, NULL),
(609, 'PT. MBJ Group', 'Engineering', NULL, '-', 'purch.mbjgroup@gmail.com', '-', '-', '-', '-', '-', '-', 'Jalan Ruko Green land Blok O No. 6, Batam - Indonesia', 'Kepulauan Riau', 'Kota Batam', '&lt;p&gt;MBJ Group is established on the Indonesian island of Batam in 2014. Our main areas of operation are in the shipping, contractor, and supplier industries, assisting in the development of Batam and the shipment of goods from Batam, with the island serving as a strategic international port. We have over 20 years of experience in our respective fields of operation and look forward to many more years successfully serving our clients and partners with high-quality products and services.&lt;/p&gt;\\r\\n', 'Verified', '1', 1, NULL, NULL),
(610, 'PT Rotary Engineering Indonesia', 'Engineering', NULL, '0778 - 392 612', 'ptrei.hrd@rotaryeng.onmicrosoft.com', 'https://www.rotaryeng.com.sg/', '-', '-', '-', '-', '-', 'Jalan Brigjen Katamso Km 6, Tanjung Uncang', 'Kepulauan Riau', 'Batam', '&lt;p&gt;PT Rotary Engineering Indoneisa a Robust One-Stop-Fabrication Provider upholding highest excellence in Safety, Quality and Productivity. Wholly-owned subsidiary of Rotary Engineering Pte. Ltd (REL)&lt;/p&gt;\\r\\n\\r\\n&lt;p&gt;Primary objective is to provide Fabrication Services (Tankage, Piping, Structural, Modular, E&amp;amp;I, Etc..) to third party and support REL fabrication requirements.&lt;/p&gt;\\r\\n', 'Verified', '1', 1, NULL, NULL),
