(613, 'PT H-Tech Oilfield Equipment ', 'Other', NULL, '0778 711 416', 'ari.wibawa@nov.com', 'https://www.nov.com/about/our-business-units/xl-systems', '-', '-', '-', '-', '-', '-Kawasan Industri Terpadu Kabil, Jl Hang Kesturi VI no 11, Batu Besar, Kecamatan Nongsa, Kota Batam, Kepulauan Riau 29467', 'Kepulauan Riau', 'Batam', '&lt;p&gt;PT H-Tech Oilfield Equipment - NOV XL Systems&lt;/p&gt;\\r\\n\\r\\n&lt;p&gt;\\\\r\\\\n\\\\r\\\\n&lt;/p&gt;\\r\\n\\r\\n&lt;p&gt;XL Systems&amp;#39; oil and gas applications include conductor strings, surface casing, liners, and caissons.&lt;/p&gt;\\r\\n\\r\\n&lt;p&gt;\\\\r\\\\n&lt;/p&gt;\\r\\n', 'Verified', '1', 1, NULL, NULL),
(614, 'PT. Prime Service International (PSI)', 'Consultant', NULL, '-', '-', 'https://ptpsi.com/', 'https://www.facebook.com/', 'https://twitter.com/psitax_official?s=08', 'https://www.instagram.com/primeservices.id/', '-', 'https://ptpsi.com/wp-content/uploads/2021/03/HP-Logo-PRIMESERVICES-international.png', 'Batam Office Graha Pena Batam 5th Floor Unit 6-9 Jl. Raya Batam Centre, Batam', 'KEPULAUAN RIAU', 'KOTA BATAM', '&lt;p&gt;TOWARD GLOBAL TAX CONSULTANT AND BUSINESS ADVISORY&lt;/p&gt;\r\n\r\n&lt;p&gt;Prime Services International (PSI) was founded in Batam in 2007. It operates primarily in Batam and Jakarta, providing tax and business advisory services. The services cover investment (primarily inbound), tax advisory including statutory compliance, advisory as well as dispute resolution, customs advisory, accounting and financial advisory services.&lt;/p&gt;\r\n\r\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\r\n\r\n&lt;p&gt;PSI was primarily founded by three partners who have accumulated a wealth of experiences serving primarily multinational companies, as well as domestic companies; certain government agencies and State-Owned Enterprises. Both have served companies in Batam since 1990.&lt;/p&gt;\r\n', 'Verified', '1', 1, NULL, NULL),
