(749, 'PT. Aspidistra ', 'Technical Consultant Company', NULL, '0778 748 1025', 'asp_btm@aspidistra.co.id,', 'http://www.aspidistra.co.id/', '-', '-', '-', '-', '-', 'Kompleks Nusantara Golden Blok B No 3, Batam, Indonesia', 'KEPULAUAN RIAU', 'KOTA BATAM', '&lt;p&gt;&lt;strong&gt;History&lt;/strong&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt;PT Aspidistra provides technical &amp;amp; consulting management since 2005 in the fields of &amp;nbsp;offshore and onshore services in Oil &amp;amp; gas company, Oil &amp;amp; Gas, Construction Company, &amp;nbsp;&amp;nbsp;Process Plant for Manufacturing&lt;/p&gt;\r\n\r\n&lt;p&gt;We have been experienced in supplying &amp;nbsp;Technical Consultant for &amp;nbsp;level Project Manager, managers, and&amp;nbsp; also level Engineers, Supervisors, various disipline. Skill&amp;nbsp; &amp;nbsp;level &amp;nbsp;for QC, Drafter, Foreman, Welders, Fitters, Riggers, Mechanical, and Electrical &amp;amp; Instrument, &amp;nbsp;and also for administration &amp;amp; supporting.&lt;/p&gt;\r\n\r\n&lt;p&gt;&amp;nbsp;&lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;strong&gt;Vision &amp;amp; Mission&lt;/strong&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;br /&gt;\r\n&lt;strong&gt;Vision&lt;/strong&gt;&lt;br /&gt;\r\nTo be a trusted and reliable company in the fields of Technical &amp;amp; Management Consultant, Manpower Recruiting &amp;amp; Provider Consultant and Logistic,Immigration, and payroll system.&lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;strong&gt;Mision&lt;/strong&gt;&lt;br /&gt;\r\nProvide professional business services in the fields of Technical &amp;amp; Management Consultant, Manpower Recruiting &amp;amp; Provider Consultant and &amp;nbsp;Logistic,Immigration, and payroll system.&lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;strong&gt;Values&lt;/strong&gt;&lt;br /&gt;\r\nWe shall perform our duties trustworthy, reliable, and competence&lt;/p&gt;\r\n\r\n&lt;p&gt;&lt;strong&gt;QUALITY POLICY&lt;/strong&gt;&lt;/p&gt;\r\n\r\n&lt;p&gt;We shall strive to give satisfaction to our customers and other stake holders, and continuosly improve our services&lt;/p&gt;\r\n', 'Verified', '1', 1, NULL, NULL),
(750, 'Sahid Batam Center Hotel &amp; Convention', 'Travel Agency', NULL, '0778 748 3336', 'rsv@sahidbatamcenter.com', 'https://sahidhotels.com/sahid-batam-center-hotel-convention/', 'https://www.facebook.com/SahidBatamCenter/', '-', 'https://www.instagram.com/sahidbatamcenter/', '-', 'https://cdn.webhotelier.net/photos/h=180:v=1/templates/5583/logo.png', 'Jalan Fisabillilah, Raffles City Complex, Block E No 6-9, Batam, Kepulauan Riau, Indonesia', 'KEPULAUAN RIAU', 'KOTA BATAM', '&lt;p&gt;Located in the heart of Batam Center, where luxury and homey abound. Sahid Batam Center Hotel and Convention boast deep connections to modern lifestyle, relaxations, Local culinary and entertainment with Roof Top Bar at Sky 8. Groups, Couples, Families, and Friends will delight in Homey and Luxurious, providing unforgettable experiences by relaxation and Hi-Technology.&lt;/p&gt;\r\n', 'Verified', '1', 1, NULL, NULL),
(751, 'PT. Vetco Gray (Golden Solution) Indonesia ', 'IT and Telecommunication', NULL, '(021) 2605 5968', 'info@gsindonesia.com', 'https://www.gsindonesia.com/', '-', '-', '-', '-', 'https://www.gsindonesia.com/wp-content/uploads/2018/05/logo.png', 'Jl. Angkasa Blok B10 No. 5, Kel. Gunung Sahari Selatan, Kec. Kemayoran, Jakarta Pusat, 10610.', 'DKI Jakarta', 'Jakarta Pusat', '&lt;p&gt;&amp;ldquo;Protecting Your World with Excellence&amp;rdquo;. PT. Golden Solution Indonesia emphasize on strong and unique solution. We provide top notch quality services to put our customers&amp;rsquo; mind in ease. We selectively choose high quality products, materials and solutions to make sure it meets our customers&amp;rsquo; need at affordable price.&lt;/p&gt;\r\n', 'Verified', '1', 1, NULL, NULL),
