INSERT INTO `maintenance_settings` (`id`, `title`, `description`, `start_date`, `end_date`, `is_active`, `allowed_ips`, `created_at`, `updated_at`) VALUES
(6, 'Server Maintenance', 'Checking System Error, Cleaning Junk File, etc', '2026-01-18 00:00:00', '2026-01-18 23:59:00', 0, '', '2026-01-17 09:47:48', NULL);
INSERT INTO `offer` (`id_offer`, `id_company`, `status`, `position`, `description`, `requirement`, `employer_type`, `city`, `job_type`, `salary_range`, `start_date`, `end_date`, `offer_type`, `timestamp_add`, `timestamp_update`) VALUES
(2, 192, 'Open', 'ACCOUNTING INTERN', '<ul>\r\n	<li>\r\n	<p><strong>BENEFITS</strong></p>\r\n\r\n	<p>&nbsp;</p>\r\n	</li>\r\n	<li>Memperoleh fasilitas keselamatan dan kesehatan kerja (BPJS KES).</li>\r\n	<li>Memperoleh perlindungan jaminan kecelakaan kerja dan kematian (BPJS TK).</li>\r\n	<li>Memperoleh uang saku.</li>\r\n	<li>Memperoleh bimbingan dari Pembimbing Pemagangan.</li>\r\n	<li>Memperoleh Sertifikat Pemagangan jika dinyatakan lulus.</li>\r\n	<li>\r\n	<p>&nbsp;</p>\r\n\r\n	<p>&nbsp;</p>\r\n\r\n	<p><strong>RESPONSIBILITIES</strong></p>\r\n	</li>\r\n	<li>Mengikuti Pemagangan sampai selesai sesuai dengan jadwal yang ditetapkan.</li>\r\n	<li>&nbsp;Periode Pemagangan selama (6-12 Bulan) dimulai 15 Maret 2023</li>\r\n	<li>Mentaati tata tertib yang berlaku.</li>\r\n	<li>Mentaati segala instruksi dari Pembimbing Pemagangan.</li>\r\n	<li>Menyelesaikan tugas atau pekerjaan yang diberikan.</li>\r\n	<li>Waktu kerja <strong>Peserta Magang</strong> adalah 8 jam sehari atau 40 jam seminggu.</li>\r\n</ul>\r\n', '<ul>\r\n	<li>Upload Photo Terkini (JPG)</li>\r\n	<li>Upload satu Resume yang berisi CV,KTP,Transkip Nilai Terakhir, Sertifikat (jika ada), Ijazah Terakhir.</li>\r\n	<li>Bersedia melaksanakan pemagangan di Head Office PT PEB, Tanjung Uncang-Batam.</li>\r\n	<li>Mahasiswa perguruan tinggi aktif &nbsp;dalam program S1/D4/D3.</li>\r\n	<li>Semua Jurusan Teknik Elektro/Teknik Informatika/Sistem Informasi/Akuntansi/ Ekonomi /Manajemen/Administrasi/Hukum.</li>\r\n	<li>IPK terakhir minimal 3 (skala 4).</li>\r\n	<li>Memiliki keterampilan komputasi (sistem operasi, Ms Office)</li>\r\n	<li>Mampu berkomunikasi dengan baik dan bekerja dalam kelompok.</li>\r\n	<li>Memiliki inisiatif, analisa yang kuat, dan mampu melakukan pemecahan masalah.</li>\r\n</ul>\r\n', 'ACCOUNTING INTERN', 'BATAM, TANJUNG UNCANG', 'ACCOUNTING INTERN', '2,000,000-3,150,000', '2023-03-15', '2023-11-15', 'Internship', '2023-02-15 07:57:17', '-'),
(3, 192, 'Open', 'HR INTERN', '<p><strong>BENEFITS</strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<ul>\r\n	<li>Memperoleh fasilitas keselamatan dan kesehatan kerja (BPJS KES).</li>\r\n	<li>Memperoleh perlindungan jaminan kecelakaan kerja dan kematian (BPJS TK).</li>\r\n	<li>Memperoleh uang saku.</li>\r\n	<li>Memperoleh bimbingan dari Pembimbing Pemagangan.</li>\r\n	<li>Memperoleh Sertifikat Pemagangan jika dinyatakan lulus.</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><strong>RESPONSIBILITIES</strong></p>\r\n\r\n<ul>\r\n	<li>Mengikuti Pemagangan sampai selesai sesuai dengan jadwal yang ditetapkan.</li>\r\n	<li>&nbsp;Periode Pemagangan selama (6-12 Bulan) dimulai 15 Maret 2023</li>\r\n	<li>Mentaati tata tertib yang berlaku.</li>\r\n	<li>Mentaati segala instruksi dari Pembimbing Pemagangan.</li>\r\n	<li>Menyelesaikan tugas atau pekerjaan yang diberikan.</li>\r\n	<li>Waktu kerja <strong>Peserta Magang</strong> adalah 8 jam sehari atau 40 jam seminggu.</li>\r\n</ul>\r\n', '<p><strong>REQUIREMENTS</strong></p>\r\n\r\n<ul>\r\n	<li>Upload Photo Terkini (JPG)</li>\r\n	<li>Upload satu Resume yang berisi CV,KTP,Transkip Nilai Terakhir, Sertifikat (jika ada), Ijazah Terakhir.</li>\r\n	<li>Bersedia melaksanakan pemagangan di Head Office PT PEB, Tanjung Uncang-Batam.</li>\r\n	<li>Mahasiswa perguruan tinggi aktif &nbsp;dalam program S1/D4/D3.</li>\r\n	<li>Semua Jurusan Teknik Elektro/Teknik Informatika/Sistem Informasi/Akuntansi/ Ekonomi /Manajemen/Administrasi/Hukum.</li>\r\n	<li>IPK terakhir minimal 3 (skala 4).</li>\r\n	<li>Memiliki keterampilan komputasi (sistem operasi, Ms Office)</li>\r\n	<li>Mampu berkomunikasi dengan baik dan bekerja dalam kelompok.</li>\r\n	<li>Memiliki inisiatif, analisa yang kuat, dan mampu melakukan pemecahan masalah.</li>\r\n</ul>\r\n', 'HR INTERN', 'BATAM, TANJUNG UNCANG', 'HR INTERN', '2,000,000-3,150,000', '2023-03-15', '2023-11-03', 'Internship', '2023-02-15 07:58:40', '-'),
